package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * When the request sets {@code sharesHousehold} true, joins the new owner to the
 * household formed by owners that share the same last name and address, using the
 * shared comparison in {@link Households} so the {@code householdId} it assigns matches
 * the one {@link EnsureUniqueIdentity} folds into the identity key.
 *
 * <p>Every owner in a household carries the same {@code householdId} — a stable
 * identifier derived from the normalized last name and address, so all members
 * compute the same value independently. The new owner receives it, and any existing
 * household members that do not yet carry it are back-filled so the whole household
 * shares one identifier.
 *
 * <p>Does nothing when {@code sharesHousehold} is absent or false, leaving a solo
 * owner's {@code householdId} null.
 */
public class AssignHousehold {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String lastName = Households.normalize(owner.getLastName());
        String address = Households.normalizeAddress(owner.getAddress());
        String householdId = Households.deriveHouseholdId(lastName, address);
        owner.setHouseholdId(householdId);
        for (Owner existing : ownerRepository.findAll()) {
            if (Households.matches(existing, lastName, address)
                    && !householdId.equals(existing.getHouseholdId())) {
                existing.setHouseholdId(householdId);
                ownerRepository.save(existing);
            }
        }
    }
}
=== Households ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Single source of truth for what a "household" is: two owners share one when their
 * last name and address match after normalization. The last name is trimmed, has runs
 * of whitespace collapsed to a single space and is lower-cased; the address uses the
 * canonical {@link OwnerAddresses} normalization (the same form that is stored and
 * returned), so the comparison always runs on the normalized address. Also derives the
 * stable {@code householdId} for a household, used both when {@link AssignHousehold}
 * joins an owner to one and when the create-time duplicate check builds an owner's
 * identity key, so the two cannot drift apart.
 */
final class Households {

    private Households() {
    }

    /** Lower-cases and collapses runs of whitespace to a single space so the comparison
     *  ignores case and incidental spacing differences. */
    static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    /** The canonical normalized address (see {@link OwnerAddresses}), used for every
     *  address comparison so it matches the stored and returned form. Never null. */
    static String normalizeAddress(String value) {
        String normalized = OwnerAddresses.normalize(value);
        return normalized == null ? "" : normalized;
    }

    /** Whether {@code existing} belongs to the household identified by the already
     *  normalized {@code lastName} and {@code address}. */
    static boolean matches(Owner existing, String normalizedLastName, String normalizedAddress) {
        return normalizedLastName.equals(normalize(existing.getLastName()))
                && normalizedAddress.equals(normalizeAddress(existing.getAddress()));
    }

    /** The {@code householdId} for the household an owner with this last name and address
     *  belongs to, derived from the raw values (normalized here first). */
    static String householdId(String rawLastName, String rawAddress) {
        return deriveHouseholdId(normalize(rawLastName), normalizeAddress(rawAddress));
    }

    /** Stable identifier for a household: the first 12 upper-case hex characters of the
     *  SHA-256 of the already-normalized last name and address joined by a NUL separator. */
    static String deriveHouseholdId(String normalizedLastName, String normalizedAddress) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest((normalizedLastName + "\u0000" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.substring(0, 12).toUpperCase(Locale.ROOT);
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }
}
=== FlagPossibleDuplicate ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Objects;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's soft-match flags. A new owner that is not a hard duplicate (the
 * hard-duplicate 409 is already decided by {@link EnsureUniqueIdentity}) is still flagged
 * as a possible duplicate when it shares an existing owner's last name (compared
 * case-insensitively) and postcode while carrying a different telephone: in that case
 * {@code possibleDuplicate} is {@code true} and {@code possibleDuplicateOf} is the matching
 * owner's id. Otherwise {@code possibleDuplicate} is {@code false} and
 * {@code possibleDuplicateOf} is null.
 *
 * <p>Runs before the owner is saved and over the existing owners only (the new owner is not
 * yet persisted); when more than one existing owner matches, the lowest id wins so the
 * result is deterministic.
 */
public class FlagPossibleDuplicate {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String lastName = OwnerNames.normalize(owner.getLastName());
        String postcode = owner.getPostcode();
        String telephone = owner.getTelephone();
        Owner match = null;
        if (postcode != null) {
            for (Owner existing : ownerRepository.findAll()) {
                if (existing.getId() == null) {
                    continue;
                }
                if (lastName.equals(OwnerNames.normalize(existing.getLastName()))
                        && postcode.equals(existing.getPostcode())
                        && !postcode.isBlank()
                        && !Objects.equals(telephone, existing.getTelephone())) {
                    if (match == null || existing.getId() < match.getId()) {
                        match = existing;
                    }
                }
            }
        }
        if (match != null) {
            owner.setPossibleDuplicate(true);
            owner.setPossibleDuplicateOf(match.getId());
        }
        else {
            owner.setPossibleDuplicate(false);
            owner.setPossibleDuplicateOf(null);
        }
    }
}

